export function Template({
  pageTitle = "{{pageTitle}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  showFooter = {{showFooter}},
}) {
  const regionBox = { background: "#24143008", borderRadius: 6, padding: 8, flex: 1, textAlign: "center" };
  return (
    <div role="img" aria-label={`${pageTitle}, ${layout} layout`} style={{ font: "11px system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontSize: 13, fontWeight: 700 }}>{pageTitle}</p>
      <div style={{ padding: 8, borderRadius: 6, textAlign: "center", fontWeight: 600, background: accent, marginBottom: 6 }}>header</div>
      <div style={{ display: "flex", gap: 6, minHeight: 70 }}>
        {layout === "sidebar" && <div style={{ background: "#24143014", borderRadius: 6, padding: 8, width: 60, textAlign: "center" }}>nav</div>}
        {(layout === "sidebar" || layout === "full-width" || layout === "split") && <div style={regionBox}>content</div>}
        {layout === "split" && <div style={regionBox}>content</div>}
      </div>
      {showFooter && <div style={{ marginTop: 6, padding: 8, borderRadius: 6, background: "#24143014", textAlign: "center" }}>footer</div>}
    </div>
  );
}
